INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000000b',1,'APPROVED','PUBLISHED',
'{"objectives":["Name common clothing items in Hindi at A1","Use पहनना to say what you wear","Describe what someone is wearing"],"explanation":{"intro":"Clothing vocabulary covers common garments and how to describe what someone is wearing in Hindi at A1.","culturalNote":"कपड़े — Clothing: कपड़ा (kapda) = cloth/fabric (singular); कपड़े (kapde) = clothes (plural). कमीज़ (kamiz) = shirt/blouse. पतलून (patloon) = trousers/pants. साड़ी (saari) = sari — six-metre draped garment — worn by millions of Indian women. कुर्ता (kurta) = long shirt — traditional North Indian garment for men and women. पगड़ी (pagdi) = turban — worn by Sikh men (mandatory for Sikhs). चप्पल (chappal) = sandal/slipper — most common footwear in India. जूते (joote) = shoes. पहनना (pahanna) = to wear/put on. पहनना is used for wearing both clothes and accessories. Cultural note: India''s textile tradition is extraordinary — Varanasi silk, Kanjivaram silk, block prints from Rajasthan, khadi (hand-spun cotton associated with Gandhi and independence). Dress codes vary enormously by region, religion and occasion."},"examples":[{"hindi":"वह आज नीली साड़ी पहन रही है।","transliteration":"Vah aaj neeli saari pahan rahi hai.","english":"She is wearing a blue sari today."},{"hindi":"मैं कुर्ता और पतलून पहनता हूँ।","transliteration":"Main kurta aur patloon pahanta hoon.","english":"I wear kurta and trousers."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name clothing items in Hindi and describe what someone is wearing."}}',
'{"items":[{"word":"कपड़े","translation":"clothes","transliteration":"kapde","pronunciation":"KAP-de","example":"कपड़े पहनना।"},{"word":"साड़ी","translation":"sari","transliteration":"saari","pronunciation":"SAA-ree","example":"साड़ी पहनना।"},{"word":"कुर्ता","translation":"long shirt/kurta","transliteration":"kurta","pronunciation":"KUR-ta","example":"कुर्ता पहनना।"},{"word":"पतलून","translation":"trousers","transliteration":"patloon","pronunciation":"pat-LOON","example":"पतलून पहनना।"},{"word":"पहनना","translation":"to wear","transliteration":"pahanna","pronunciation":"pa-HAN-na","example":"कपड़े पहनना।"},{"word":"चप्पल","translation":"sandal/slipper","transliteration":"chappal","pronunciation":"CHAP-pal","example":"चप्पल पहनना।"}]}',
'{"title":"X पहन रहा/रही है — X is wearing (continuous present with रहा/रही)","pattern":"Subject + object + पहन रहा/रही/रहे है/हैं = is/are wearing. Continuous present: verb stem + रहा (masc. sg.) / रही (fem. sg.) / रहे (masc. pl.) + है/हैं. पहनना = to wear (stem: पहन). Vah pahan rahi hai = She is wearing (rahi = fem. sg. continuous marker).","explanation":"Continuous present in Hindi: verb stem + रहा/रही/रहे + है/हैं. रहा = masculine singular. रही = feminine singular. रहे = masculine plural. पहनना (to wear): stem = पहन. मैं पहन रहा हूँ (I am wearing — masc.). मैं पहन रही हूँ (I am wearing — fem.). Contrast with simple habitual: मैं पहनता हूँ (I wear — habitual, masculine). Continuous present describes what is happening RIGHT NOW; habitual present describes routine/general truths.","examples":[{"sentence":"वह लाल कमीज़ पहन रहा है।","transliteration":"Vah lal kamiz pahan raha hai.","translation":"He is wearing a red shirt."},{"sentence":"बच्चे जूते पहन रहे हैं।","transliteration":"Bachche joote pahan rahe hain.","translation":"The children are wearing shoes."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"पहनना means?","options":["to wear","to buy","to wash","to fold"],"correctAnswer":"to wear"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"She is wearing a blue sari today.","options":["वह आज नीली साड़ी पहन रही है।","वह आज लाल साड़ी पहन रही है।","वह कल नीली साड़ी पहन रही है।","वह आज नीला कुर्ता पहन रही है।"],"correctAnswer":"वह आज नीली साड़ी पहन रही है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"वह लाल कमीज़ पहन ___ है।","options":["रहा","रही","रहे","रहता"],"correctAnswer":"रहा"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The children are wearing shoes.","wordBankItems":["बच्चे","जूते","पहन","रहे","हैं","।"],"correctAnswer":"बच्चे जूते पहन रहे हैं ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"साड़ी means?","options":["sari","shirt","kurta","trousers"],"correctAnswer":"sari"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000000c',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe the weather in Hindi at A1","Use मौसम है/हो रहा है constructions","Talk about seasons and basic weather conditions"],"explanation":{"intro":"Weather vocabulary covers common weather conditions and how to describe them in Hindi at A1.","culturalNote":"मौसम — Weather: मौसम (mausam) = weather (from Arabic mawsim = season, via Persian — same root as ''monsoon''). गर्मी (garmi) = heat/summer. सर्दी (sardi) = cold/winter. बारिश (barish) = rain. धूप (dhoop) = sunshine/sunlight. आँधी (aandhi) = dust storm/strong wind — common in North India. बाढ़ (baadh) = flood. भारत में चार मुख्य मौसम हैं (Bharat mein char mukhya mausam hain = India has four main seasons): ग्रीष्म (greeshma = summer), मानसून (monsoon = June-September), शरद (sharad = autumn), शीत (sheet = winter). The monsoon is critical for India — agriculture, water supply, festivals. मानसून की पहली बारिश (first rains of monsoon) is celebrated as a relief after the scorching summer. बारिश हो रही है (barish ho rahi hai = it is raining — continuous present)."},"examples":[{"hindi":"आज बहुत गर्मी है।","transliteration":"Aaj bahut garmi hai.","english":"Today it is very hot."},{"hindi":"बाहर बारिश हो रही है।","transliteration":"Bahar barish ho rahi hai.","english":"It is raining outside."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe the weather in Hindi and talk about seasons."}}',
'{"items":[{"word":"मौसम","translation":"weather/season","transliteration":"mausam","pronunciation":"MOW-sam","example":"आज का मौसम।"},{"word":"गर्मी","translation":"heat/summer","transliteration":"garmi","pronunciation":"GAR-mee","example":"बहुत गर्मी है।"},{"word":"सर्दी","translation":"cold/winter","transliteration":"sardi","pronunciation":"SAR-dee","example":"सर्दी है।"},{"word":"बारिश","translation":"rain","transliteration":"barish","pronunciation":"BA-rish","example":"बारिश हो रही है।"},{"word":"धूप","translation":"sunshine/sunlight","transliteration":"dhoop","pronunciation":"dhoop","example":"धूप निकली है।"},{"word":"बाहर","translation":"outside","transliteration":"bahar","pronunciation":"BA-har","example":"बाहर ठंड है।"}]}',
'{"title":"X हो रहा/रही है — X is happening (continuous present of होना for weather)","pattern":"Weather noun + हो रहा/रही है = weather noun is happening (it is raining/snowing etc.). बारिश हो रही है = it is raining (barish = rain + ho rahi hai = is happening — feminine because barish is feminine). गर्मी हो रही है / गर्मी है = it is getting hot / it is hot. Weather in Hindi uses noun-based constructions: बारिश (rain-noun) + हो रही है. Contrast: English uses verb ''to rain''; Hindi uses noun ''rain'' + होना ''to be/happen.''","explanation":"Weather constructions in Hindi use होना (to be/happen) rather than a weather verb. बारिश (barish) = rain (feminine noun). हो रही है = is happening (feminine continuous: ho rahi hai). बर्फ़ पड़ रही है (barf pad rahi hai = it is snowing — barf = snow, padna = to fall). धूप निकल रही है (dhoop nikal rahi hai = the sun is coming out — nikalna = to emerge). गर्मी है (garmi hai = it is hot) — simple present for states. बारिश हो रही है (barish ho rahi hai) — continuous for ongoing actions.","examples":[{"sentence":"आज बहुत ठंड है।","transliteration":"Aaj bahut thand hai.","translation":"Today it is very cold."},{"sentence":"कल बारिश थी।","transliteration":"Kal barish thi.","translation":"Yesterday there was rain."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"मौसम means?","options":["weather","season","rain","sun"],"correctAnswer":"weather"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"It is raining outside.","options":["बाहर बारिश हो रही है।","अंदर बारिश हो रही है।","बाहर धूप हो रही है।","बाहर बारिश थी।"],"correctAnswer":"बाहर बारिश हो रही है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"आज बहुत ___ है।","options":["गर्मी","बारिश","धूप","मौसम"],"correctAnswer":"गर्मी"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Yesterday there was rain.","wordBankItems":["कल","बारिश","थी","।"],"correctAnswer":"कल बारिश थी ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"बारिश means?","options":["rain","wind","storm","flood"],"correctAnswer":"rain"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000000d',1,'APPROVED','PUBLISHED',
'{"objectives":["Name common animals in Hindi at A1","Use यह/वह with animals","Describe animals with simple adjectives"],"explanation":{"intro":"Animals vocabulary covers common domestic and wild animals and how to describe them simply in Hindi at A1.","culturalNote":"जानवर — Animals: जानवर (jaanvar) = animal (from Persian jaanvar = living being). गाय (gaay) = cow — sacred in Hinduism — national animal controversy. बैल (bail) = bull/ox — key for farming historically. हाथी (haathi) = elephant — national heritage animal of India. बाघ (baagh) = tiger — national animal of India (Project Tiger 1973). शेर (sher) = lion. कुत्ता (kutta) = dog. बिल्ली (billi) = cat. चिड़िया (chidiya) = bird (generic small bird). मोर (mor) = peacock — national bird of India. गाय को ''माता'' कहते हैं (gaay ko mata kahte hain = cow is called mother — traditional Hindu respect). Key: Devanagari conjunct consonants — हाथी has the ा matra (long a) on ह. Cultural: India has extraordinary biodiversity — Bengal tigers, Indian elephants, Asiatic lions (only in Gir forest), snow leopards, one-horned rhinoceros."},"examples":[{"hindi":"भारत का राष्ट्रीय पशु बाघ है।","transliteration":"Bharat ka rashtriya pashu baagh hai.","english":"India''s national animal is the tiger."},{"hindi":"हमारे घर में एक कुत्ता और दो बिल्लियाँ हैं।","transliteration":"Hamaare ghar mein ek kutta aur do billiyan hain.","english":"In our house there is one dog and two cats."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name common animals in Hindi and describe them simply."}}',
'{"items":[{"word":"जानवर","translation":"animal","transliteration":"jaanvar","pronunciation":"JAAN-var","example":"जंगली जानवर।"},{"word":"गाय","translation":"cow","transliteration":"gaay","pronunciation":"gaay","example":"गाय दूध देती है।"},{"word":"हाथी","translation":"elephant","transliteration":"haathi","pronunciation":"HAATH-ee","example":"बड़ा हाथी।"},{"word":"बाघ","translation":"tiger","transliteration":"baagh","pronunciation":"baagh","example":"बाघ जंगल में।"},{"word":"कुत्ता","translation":"dog","transliteration":"kutta","pronunciation":"KUT-ta","example":"मेरा कुत्ता।"},{"word":"बिल्ली","translation":"cat","transliteration":"billi","pronunciation":"BIL-lee","example":"काली बिल्ली।"}]}',
'{"title":"X का राष्ट्रीय Y Z है — X''s national Y is Z (का for possession/of)","pattern":"X का Y = X''s Y / Y of X. का = of/''s (masculine possessive). की = of/''s (feminine possessive). के = of/''s (oblique masculine plural). भारत का राष्ट्रीय पशु = India''s national animal. Agreement: का/की/के agrees with the POSSESSED noun (Y), not the possessor (X). राष्ट्रीय पशु (rashtriya pashu) = national animal — पशु is masculine → का.","explanation":"Possessive postposition: का/की/के follow the possessor and agree with the possessed. Masculine singular noun: का. Feminine singular noun: की. Masculine plural noun: के. Feminine plural noun: की. भारत का बाघ = India''s tiger (पशु is masculine → का). भारत की नदी = India''s river (नदी = river is feminine → की). भारत के पहाड़ = India''s mountains (पहाड़ is masculine plural → के). Important: when the possessed noun takes a postposition (oblique case), का → के regardless of gender.","examples":[{"sentence":"मेरे कुत्ते का नाम टॉमी है।","transliteration":"Mere kutte ka naam Tommy hai.","translation":"My dog''s name is Tommy."},{"sentence":"भारत की राजधानी दिल्ली है।","transliteration":"Bharat ki rajdhani Dilli hai.","translation":"India''s capital is Delhi."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"बाघ means?","options":["tiger","lion","elephant","bear"],"correctAnswer":"tiger"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"India''s national animal is the tiger.","options":["भारत का राष्ट्रीय पशु बाघ है।","भारत का राष्ट्रीय पक्षी बाघ है।","भारत का राष्ट्रीय पशु शेर है।","भारत की राष्ट्रीय पशु बाघ है।"],"correctAnswer":"भारत का राष्ट्रीय पशु बाघ है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"भारत की राजधानी ___ है।","options":["दिल्ली","मुंबई","कोलकाता","चेन्नई"],"correctAnswer":"दिल्ली"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My dog''s name is Tommy.","wordBankItems":["मेरे","कुत्ते","का","नाम","टॉमी","है","।"],"correctAnswer":"मेरे कुत्ते का नाम टॉमी है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"गाय means?","options":["cow","goat","buffalo","sheep"],"correctAnswer":"cow"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000000e',1,'APPROVED','PUBLISHED',
'{"objectives":["Name school subjects and classroom items in Hindi at A1","Use पढ़ना to talk about studying","Describe a school day"],"explanation":{"intro":"School vocabulary covers subjects, classroom items, and common school-day phrases in Hindi at A1.","culturalNote":"स्कूल — School: स्कूल (school) = school (English loanword — widely used). विद्यालय (vidyalay) = school (Sanskrit — formal). कक्षा (kaksha) = class/classroom. अध्यापक/अध्यापिका (adhyapak/adhyapika) = teacher (male/female). पढ़ना (padhna) = to read/study. लिखना (likhna) = to write. किताब (kitaab) = book. कॉपी (copy) = notebook (anglicism). पेंसिल (pencil) = pencil. कलम (kalam) = pen (also: बॉलपेन). Cultural note: India has a vast and complex education system — 250 million school students (world''s largest). IITs (Indian Institutes of Technology) are globally renowned. भारतीय शिक्षा प्रणाली (Bharatiya shiksha pranali = Indian education system). Gurukul (गुरुकुल) = traditional guru-based education — guru = teacher, kul = family. IIT-JEE entrance exam is one of the world''s most competitive. Mid-day meal scheme (mid-day meal = hot meals in govt schools)."},"examples":[{"hindi":"मैं हिंदी और गणित पढ़ता हूँ।","transliteration":"Main Hindi aur ganit padhta hoon.","english":"I study Hindi and mathematics."},{"hindi":"कक्षा में पच्चीस बच्चे हैं।","transliteration":"Kaksha mein pachees bachche hain.","english":"In the class there are twenty-five children."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name school subjects and talk about studying in Hindi."}}',
'{"items":[{"word":"पढ़ना","translation":"to read/study","transliteration":"padhna","pronunciation":"PADH-na","example":"किताब पढ़ना।"},{"word":"लिखना","translation":"to write","transliteration":"likhna","pronunciation":"LIKH-na","example":"लिखना सीखना।"},{"word":"कक्षा","translation":"class/classroom","transliteration":"kaksha","pronunciation":"KAK-sha","example":"मेरी कक्षा।"},{"word":"किताब","translation":"book","transliteration":"kitaab","pronunciation":"ki-TAAB","example":"हिंदी की किताब।"},{"word":"गणित","translation":"mathematics","transliteration":"ganit","pronunciation":"GA-nit","example":"गणित पढ़ना।"},{"word":"अध्यापक","translation":"teacher (male)","transliteration":"adhyapak","pronunciation":"adh-YA-pak","example":"मेरे अध्यापक।"}]}',
'{"title":"मैं X पढ़ता/पढ़ती हूँ — I study X (habitual present, gender agreement)","pattern":"मैं X पढ़ता हूँ (male speaker) / मैं X पढ़ती हूँ (female speaker). Habitual present = verb stem + ता/ती/ते + हूँ/है/हैं. पढ़ना stem = पढ़. ता = masculine singular. ती = feminine singular. ते = masculine plural. Agreement: matches the SUBJECT''s gender (not the object).","explanation":"Habitual present tense: verb stem + ता/ती/ते + auxiliary. Used for: routines, habits, general truths, abilities. Agreement table for पढ़ना (to read/study): मैं पढ़ता हूँ (I study — male). मैं पढ़ती हूँ (I study — female). तुम पढ़ते हो (you study — informal). आप पढ़ते हैं (you study — formal). वह पढ़ता है (he studies). वह पढ़ती है (she studies). हम पढ़ते हैं (we study). वे पढ़ते हैं (they study).","examples":[{"sentence":"वह रोज़ किताब पढ़ती है।","transliteration":"Vah roz kitaab padhti hai.","translation":"She reads a book every day."},{"sentence":"हम अंग्रेज़ी पढ़ते हैं।","transliteration":"Hum angrezi padhte hain.","translation":"We study English."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"पढ़ना means?","options":["to read/study","to write","to teach","to learn"],"correctAnswer":"to read/study"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I study Hindi and mathematics.","options":["मैं हिंदी और गणित पढ़ता हूँ।","मैं हिंदी और विज्ञान पढ़ता हूँ।","मैं हिंदी और गणित लिखता हूँ।","मैं हिंदी और गणित पढ़ती हूँ।"],"correctAnswer":"मैं हिंदी और गणित पढ़ता हूँ।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"वह रोज़ किताब ___ है।","options":["पढ़ती","पढ़ता","पढ़ते","पढ़ना"],"correctAnswer":"पढ़ती"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We study English.","wordBankItems":["हम","अंग्रेज़ी","पढ़ते","हैं","।"],"correctAnswer":"हम अंग्रेज़ी पढ़ते हैं ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"गणित means?","options":["mathematics","science","history","Hindi"],"correctAnswer":"mathematics"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000000f',1,'APPROVED','PUBLISHED',
'{"objectives":["Navigate the market and ask prices in Hindi at A1","Use कितने का/की है? to ask the price","Buy and sell interactions"],"explanation":{"intro":"Market vocabulary covers shopping, prices, and basic buying-selling interactions in Hindi at A1.","culturalNote":"बाज़ार — The Market: बाज़ार (baazaar) = market (from Persian bazar — same root as English ''bazaar''). दुकान (dukaan) = shop. दुकानदार (dukaandaar) = shopkeeper. सब्ज़ी (sabzi) = vegetables. फल (phal) = fruit. कितने का है? (Kitne ka hai?) = How much does it cost? (literally: for how much is it?). कितने रुपये? (Kitne rupaye?) = How many rupees? मोल-भाव (mol-bhaav) = bargaining — essential skill in Indian markets. Indian rupee (₹) = रुपया (rupaya). हाट (haat) = weekly village market. मंडी (mandi) = wholesale market. Cultural: India''s bazaar culture is ancient and vibrant — Chandni Chowk in Old Delhi is one of Asia''s oldest markets. Street vendors (रेहड़ी वाला = rehdi wala). Shopping malls (शॉपिंग मॉल) now also widespread in cities. Haggling is normal in markets but not in branded shops."},"examples":[{"hindi":"यह सेब कितने का है?","transliteration":"Yah seb kitne ka hai?","english":"How much does this apple cost?"},{"hindi":"पाँच रुपये किलो।","transliteration":"Paanch rupaye kilo.","english":"Five rupees a kilo."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can ask prices in a Hindi market and conduct basic shopping interactions."}}',
'{"items":[{"word":"बाज़ार","translation":"market","transliteration":"baazaar","pronunciation":"BAA-zaar","example":"बाज़ार जाना।"},{"word":"दुकान","translation":"shop","transliteration":"dukaan","pronunciation":"du-KAAN","example":"दुकान खुली है।"},{"word":"कितने का है?","translation":"how much does it cost?","transliteration":"kitne ka hai?","pronunciation":"KIT-ne ka hai","example":"यह कितने का है?"},{"word":"रुपया","translation":"rupee","transliteration":"rupaya","pronunciation":"ru-PA-ya","example":"दस रुपये।"},{"word":"सब्ज़ी","translation":"vegetables","transliteration":"sabzi","pronunciation":"SAB-zee","example":"सब्ज़ी खरीदना।"},{"word":"महँगा/सस्ता","translation":"expensive/cheap","transliteration":"mahanga/sasta","pronunciation":"ma-HAN-ga/SAS-ta","example":"बहुत महँगा है।"}]}',
'{"title":"X कितने का/की है? — How much does X cost? (का/की agrees with X)","pattern":"X कितने का है? = How much does X cost? (masculine X — ka agrees). X कितने की है? = How much does X cost? (feminine X — ki agrees). का/की agrees with the gender of X (the item being sold). कितने = how many/how much (oblique plural — used for amounts). Examples: सेब कितने का है? (apple — masculine → का). सब्ज़ी कितने की है? (vegetable — feminine → की).","explanation":"Price question: कितने का/की है? — कितने (how much, oblique plural used for price queries even for singular items — standard idiomatic usage). का for masculine items: सेब (apple — masc.) → कितने का? की for feminine items: सब्ज़ी (vegetable — fem.) → कितने की? Answer pattern: X रुपये (Y rupees). Example answer: दस रुपये किलो (das rupaye kilo = ten rupees a kilo). Alternative: कितने पैसे? (kitne paise = how many paise — for smaller amounts — 1 rupee = 100 paise).","examples":[{"sentence":"यह किताब कितने की है?","transliteration":"Yah kitaab kitne ki hai?","translation":"How much does this book cost?"},{"sentence":"ये जूते कितने के हैं?","transliteration":"Ye joote kitne ke hain?","translation":"How much do these shoes cost?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"बाज़ार means?","options":["market","shop","street","city"],"correctAnswer":"market"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"How much does this apple cost?","options":["यह सेब कितने का है?","यह सेब कितने की है?","यह आम कितने का है?","यह सेब कितने रुपये है?"],"correctAnswer":"यह सेब कितने का है?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"यह किताब कितने ___ है?","options":["की","का","के","को"],"correctAnswer":"की"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: How much do these shoes cost?","wordBankItems":["ये","जूते","कितने","के","हैं","?"],"correctAnswer":"ये जूते कितने के हैं ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"महँगा means?","options":["expensive","cheap","good","bad"],"correctAnswer":"expensive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000010',1,'APPROVED','PUBLISHED',
'{"objectives":["Name transport modes in Hindi at A1","Use X से जाना to say how you travel","Ask for and give directions"],"explanation":{"intro":"Travel and transport vocabulary covers modes of transport and how to say how you travel somewhere in Hindi at A1.","culturalNote":"यात्रा — Travel and Transport: यात्रा (yatra) = journey/travel (Sanskrit — also: तीर्थ यात्रा = pilgrimage). बस (bus) = bus. ट्रेन (train) = train. ऑटो-रिक्शा (auto-rickshaw) = three-wheeled taxi — ubiquitous in Indian cities. रिक्शा (ricksha) = cycle rickshaw. टैक्सी (taxi) = taxi. हवाई जहाज़ (hawai jahaz) = aeroplane (hawai = air + jahaz = ship). मेट्रो (metro) = metro/subway. Key phrase: X से जाना = to go by X (se = by/via). कहाँ जा रहे हैं? (kahaan ja rahe hain? = where are you going? — formal). मुझे X जाना है (Mujhe X jaana hai = I need to go to X). Cultural: Indian Railways (भारतीय रेलवे) — world''s 4th largest — 14 million passengers/day. The dabbawaala (डब्बेवाला) lunch delivery system in Mumbai uses trains. Auto-rickshaws are metered in cities but bargaining is common. रेलवे स्टेशन (railway station), बस अड्डा (bus adda = bus stand)."},"examples":[{"hindi":"मैं बस से दफ़्तर जाता हूँ।","transliteration":"Main bus se daftar jaata hoon.","english":"I go to the office by bus."},{"hindi":"स्टेशन कहाँ है?","transliteration":"Station kahaan hai?","english":"Where is the station?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name transport modes in Hindi and say how I travel somewhere."}}',
'{"items":[{"word":"यात्रा","translation":"journey/travel","transliteration":"yatra","pronunciation":"YA-tra","example":"लंबी यात्रा।"},{"word":"बस","translation":"bus","transliteration":"bus","pronunciation":"bus","example":"बस से जाना।"},{"word":"ट्रेन","translation":"train","transliteration":"train","pronunciation":"train","example":"ट्रेन पकड़ना।"},{"word":"ऑटो-रिक्शा","translation":"auto-rickshaw","transliteration":"auto-ricksha","pronunciation":"ow-to RIK-sha","example":"ऑटो-रिक्शा लेना।"},{"word":"से जाना","translation":"to go by (vehicle)","transliteration":"se jaana","pronunciation":"se JAA-na","example":"बस से जाना।"},{"word":"स्टेशन","translation":"station","transliteration":"station","pronunciation":"STE-shun","example":"रेलवे स्टेशन।"}]}',
'{"title":"X से Y जाना — to go to Y by X (से = by/via for transport)","pattern":"Vehicle + से + destination + जाना = to go to destination by vehicle. से = by/via (postposition with transport — same से as ''from'' but different meaning in transport context). मैं बस से दफ़्तर जाता हूँ = I go to the office by bus (bus se = by bus; daftar = office; jaata hoon = habitual go — masculine).","explanation":"Transport: X से = by X (vehicle). से has multiple meanings: from (मैं दिल्ली से हूँ), by/with (बस से जाना), than (तुमसे बड़ा = bigger than you). Context determines meaning. Transport से: always with a vehicle name. Destination takes no postposition when it''s the direct destination (daftar jaata hoon = go-to-office). Except when there''s a postposition marker: बाज़ार को जाना (going towards the market). Common: वह पैदल जाता है (vah paidal jaata hai = he goes on foot — paidal = on foot — no ''से'' for walking).","examples":[{"sentence":"वे हवाई जहाज़ से मुंबई गए।","transliteration":"Ve hawai jahaz se Mumbai gaye.","translation":"They went to Mumbai by aeroplane."},{"sentence":"मैं पैदल स्कूल जाता हूँ।","transliteration":"Main paidal school jaata hoon.","translation":"I go to school on foot."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"यात्रा means?","options":["journey/travel","vehicle","station","road"],"correctAnswer":"journey/travel"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I go to the office by bus.","options":["मैं बस से दफ़्तर जाता हूँ।","मैं ट्रेन से दफ़्तर जाता हूँ।","मैं बस से घर जाता हूँ।","मैं बस से दफ़्तर जाती हूँ।"],"correctAnswer":"मैं बस से दफ़्तर जाता हूँ।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"वे हवाई जहाज़ ___ मुंबई गए।","options":["से","को","में","पर"],"correctAnswer":"से"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I go to school on foot.","wordBankItems":["मैं","पैदल","स्कूल","जाता","हूँ","।"],"correctAnswer":"मैं पैदल स्कूल जाता हूँ ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"ट्रेन means?","options":["train","bus","plane","rickshaw"],"correctAnswer":"train"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000011',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a daily routine in Hindi at A1","Use habitual present tense for daily activities","Use time adverbs for sequencing"],"explanation":{"intro":"Daily routine vocabulary covers common everyday activities and how to describe a routine day in Hindi at A1.","culturalNote":"रोज़मर्रा की दिनचर्या — Daily Routine: दिनचर्या (dincharya) = daily routine (din = day + charya = conduct/practice — Sanskrit). उठना (uthna) = to wake up/get up. नहाना (nahaana) = to bathe. खाना खाना (khaana khaana) = to eat food (reduplication: noun + verb). काम करना (kaam karna) = to work. सोना (sona) = to sleep. सुबह (subah) = morning. दोपहर (dopahar) = afternoon/midday (do = two + pahar = watch/period). शाम (shaam) = evening. रात (raat) = night. Cultural: Yoga and meditation (योग और ध्यान = yog aur dhyan) are common morning practices. Chai breaks (चाय का समय = chai ka samay) are embedded in office and home culture. नमाज़ (namaaz) for Muslim daily prayer five times. Puja (पूजा) for Hindu morning/evening worship. India''s diverse religious practices mean daily routines vary enormously. पहले (pahle = first), फिर (phir = then), आख़िर में (aakhir mein = finally) for sequencing."},"examples":[{"hindi":"मैं सुबह सात बजे उठता हूँ, नहाता हूँ और फिर नाश्ता करता हूँ।","transliteration":"Main subah saat baje uthta hoon, nahata hoon aur phir nashta karta hoon.","english":"I wake up at seven in the morning, bathe and then have breakfast."},{"hindi":"शाम को मैं टहलने जाता हूँ।","transliteration":"Shaam ko main tahalne jaata hoon.","english":"In the evening I go for a walk."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe a daily routine in Hindi using time adverbs and habitual present."}}',
'{"items":[{"word":"उठना","translation":"to wake up/get up","transliteration":"uthna","pronunciation":"UTH-na","example":"सुबह उठना।"},{"word":"नहाना","translation":"to bathe","transliteration":"nahaana","pronunciation":"na-HAA-na","example":"रोज़ नहाना।"},{"word":"नाश्ता","translation":"breakfast","transliteration":"nashta","pronunciation":"NASH-ta","example":"नाश्ता करना।"},{"word":"काम करना","translation":"to work","transliteration":"kaam karna","pronunciation":"kaam KAR-na","example":"दफ़्तर में काम करना।"},{"word":"सोना","translation":"to sleep","transliteration":"sona","pronunciation":"SO-na","example":"रात को सोना।"},{"word":"फिर","translation":"then/after that","transliteration":"phir","pronunciation":"phir","example":"नहाता हूँ, फिर खाता हूँ।"}]}',
'{"title":"पहले X, फिर Y — first X, then Y (sequence with time adverbs)","pattern":"पहले X, फिर Y = first X, then Y. पहले = first (time adverb). फिर = then, after that (time adverb for sequence). आख़िर में = finally. Used for sequencing routine activities. Hindi routine description: time + activity in sequence, all habitual present.","explanation":"Sequence adverbs: पहले (pahle) = first, फिर (phir) = then/next, उसके बाद (uske baad) = after that, आख़िर में (aakhir mein) = finally. These precede the verb phrase they modify: पहले उठता हूँ, फिर नहाता हूँ = first I get up, then I bathe. Time adverbs in Hindi precede the action they describe. The habitual present links them all: multiple habitual-present clauses joined by commas and conjunctions describe a routine.","examples":[{"sentence":"पहले मैं नाश्ता करता हूँ, फिर स्कूल जाता हूँ।","transliteration":"Pahle main nashta karta hoon, phir school jaata hoon.","translation":"First I have breakfast, then I go to school."},{"sentence":"पहले काम, फिर खेल।","transliteration":"Pahle kaam, phir khel.","translation":"First work, then play."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"नाश्ता means?","options":["breakfast","lunch","dinner","snack"],"correctAnswer":"breakfast"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I wake up at seven in the morning, bathe and then have breakfast.","options":["मैं सुबह सात बजे उठता हूँ, नहाता हूँ और फिर नाश्ता करता हूँ।","मैं सुबह छह बजे उठता हूँ, नहाता हूँ और फिर नाश्ता करता हूँ।","मैं सुबह सात बजे उठता हूँ और फिर नाश्ता करता हूँ।","मैं सुबह सात बजे उठती हूँ, नहाती हूँ और फिर नाश्ता करती हूँ।"],"correctAnswer":"मैं सुबह सात बजे उठता हूँ, नहाता हूँ और फिर नाश्ता करता हूँ।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"पहले मैं नाश्ता करता हूँ, ___ स्कूल जाता हूँ।","options":["फिर","पहले","बाद","आख़िर"],"correctAnswer":"फिर"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: First work, then play.","wordBankItems":["पहले","काम",",","फिर","खेल","।"],"correctAnswer":"पहले काम , फिर खेल ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"सोना means?","options":["to sleep","to rest","gold","to lie down"],"correctAnswer":"to sleep"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000012',1,'APPROVED','PUBLISHED',
'{"objectives":["Name the months and seasons in Hindi at A1","Use X में for ''in (month)''","Describe seasonal activities"],"explanation":{"intro":"Months and seasons vocabulary covers all 12 months, the main seasons, and seasonal activities in Hindi at A1.","culturalNote":"महीने और मौसम — Months and Seasons: Hindi month names come from both the Gregorian calendar (anglicised) and traditional Hindu calendar. Common Gregorian: जनवरी (January), फरवरी (February), मार्च (March), अप्रैल (April), मई (May), जून (June), जुलाई (July), अगस्त (August), सितंबर (September), अक्टूबर (October), नवंबर (November), दिसंबर (December). Indian seasons: गर्मी/ग्रीष्म (garmi/greeshma = summer — March-June — extreme heat in North India), मानसून (monsoon — July-September), शरद ऋतु (sharad ritu = autumn — October-November), सर्दी/शीत (sardi/sheet = winter — December-February). Traditional Hindu months: चैत्र, वैशाख, etc. — used for religious calendar. Festivals are tied to seasons: होली (Holi = spring, Falgun), दीपावली (Diwali = autumn, Kartik), Eid follows lunar calendar. ''ऋतु'' (ritu) = season (Sanskrit — formal); ''मौसम'' (mausam) = weather/season (everyday)."},"examples":[{"hindi":"जनवरी में बहुत सर्दी होती है।","transliteration":"January mein bahut sardi hoti hai.","english":"In January it is very cold."},{"hindi":"मेरा जन्मदिन मार्च में है।","transliteration":"Mera janamdin March mein hai.","english":"My birthday is in March."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name the months in Hindi and describe seasonal weather."}}',
'{"items":[{"word":"जनवरी","translation":"January","transliteration":"January","pronunciation":"JAN-va-ree","example":"जनवरी में सर्दी।"},{"word":"जून","translation":"June","transliteration":"June","pronunciation":"joon","example":"जून में गर्मी।"},{"word":"मानसून","translation":"monsoon","transliteration":"monsoon","pronunciation":"man-SOON","example":"मानसून में बारिश।"},{"word":"जन्मदिन","translation":"birthday","transliteration":"janamdin","pronunciation":"ja-NAM-din","example":"मेरा जन्मदिन।"},{"word":"ऋतु","translation":"season","transliteration":"ritu","pronunciation":"ri-TU","example":"शरद ऋतु।"},{"word":"साल","translation":"year","transliteration":"saal","pronunciation":"saal","example":"इस साल।"}]}',
'{"title":"X में Y होती/होता है — In X there is/are Y (habitual occurrence in a time period)","pattern":"Month/Season + में + weather/event + होती/होता है = In month/season, weather/event occurs habitually. होती है = feminine habitual (for feminine nouns like सर्दी, बारिश). होता है = masculine habitual (for masculine nouns). X में = in X (time period). Used for seasonal truths: जनवरी में सर्दी होती है = In January it is cold.","explanation":"X में for time periods: the postposition में (in) is used for months, seasons, and longer time periods. जनवरी में (in January), गर्मी में (in summer), इस साल (this year — no में needed with isa/is/this). Habitual occurrence: होती है/होता है (hoti hai/hota hai = occurs habitually — feminine/masculine). Contrast: है alone (it is — current state). होती है (it habitually is/occurs — seasonal/routine pattern). जनवरी में बहुत सर्दी होती है = In January it is always/habitually very cold (habitual truth about the month, not just today).","examples":[{"sentence":"मार्च में होली होती है।","transliteration":"March mein Holi hoti hai.","translation":"Holi takes place in March."},{"sentence":"जुलाई में मानसून होता है।","transliteration":"July mein monsoon hota hai.","translation":"The monsoon is in July."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"जन्मदिन means?","options":["birthday","festival","holiday","anniversary"],"correctAnswer":"birthday"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In January it is very cold.","options":["जनवरी में बहुत सर्दी होती है।","जनवरी में बहुत गर्मी होती है।","फरवरी में बहुत सर्दी होती है।","जनवरी में बहुत सर्दी है।"],"correctAnswer":"जनवरी में बहुत सर्दी होती है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मार्च ___ होली होती है।","options":["में","को","पर","से"],"correctAnswer":"में"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My birthday is in March.","wordBankItems":["मेरा","जन्मदिन","मार्च","में","है","।"],"correctAnswer":"मेरा जन्मदिन मार्च में है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"मानसून means?","options":["monsoon","summer","winter","spring"],"correctAnswer":"monsoon"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000013',1,'APPROVED','PUBLISHED',
'{"objectives":["Count from 11 to 100 in Hindi at A1","Learn Hindi number patterns for teens and decades","Use higher numbers in simple sentences"],"explanation":{"intro":"Numbers 11-100 covers the Hindi number system including teens and multiples of 10 at A1.","culturalNote":"संख्याएँ 11-100: Hindi has unique number words — not fully compositional until 100. Key pattern: teens are unique (ग्यारह=11, बारह=12, तेरह=13, चौदह=14, पंद्रह=15, सोलह=16, सत्रह=17, अठारह=18, उन्नीस=19). Decades: बीस=20, तीस=30, चालीस=40, पचास=50, साठ=60, सत्तर=70, अस्सी=80, नब्बे=90, सौ=100. Compound numbers 21-99: each is a unique word but follows a pattern. 21=इक्कीस, 22=बाईस, 23=तेईस, 24=चौबीस, 25=पच्चीस. The pattern shifts at each decade. Key cultural uses: उम्र (umra = age), मूल्य (mulya = price), दूरी (doori = distance). India counts in lakhs (1,00,000=lakh) and crores (1,00,00,000=crore) rather than millions/billions — number system is structured around these units. लाख (lakh), करोड़ (crore). 50=पचास is important for telling half hours (साढ़े बारह = 12:30)."},"examples":[{"hindi":"मेरे दादाजी पचहत्तर साल के हैं।","transliteration":"Mere daadaji pachattar saal ke hain.","english":"My grandfather is seventy-five years old."},{"hindi":"इस कक्षा में पैंतीस बच्चे हैं।","transliteration":"Is kaksha mein painthees bachche hain.","english":"In this class there are thirty-five children."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can count from 11 to 100 in Hindi and use higher numbers in sentences."}}',
'{"items":[{"word":"ग्यारह","translation":"eleven","transliteration":"gyaarah","pronunciation":"GYAA-rah","example":"ग्यारह बजे।"},{"word":"बीस","translation":"twenty","transliteration":"bees","pronunciation":"bees","example":"बीस रुपये।"},{"word":"पचास","translation":"fifty","transliteration":"pachaas","pronunciation":"pa-CHAAS","example":"पचास साल।"},{"word":"सौ","translation":"one hundred","transliteration":"sau","pronunciation":"sau","example":"सौ रुपये।"},{"word":"उम्र","translation":"age","transliteration":"umra","pronunciation":"um-RA","example":"मेरी उम्र।"},{"word":"साल के हैं","translation":"years old (plural respectful)","transliteration":"saal ke hain","pronunciation":"saal ke hain","example":"पचहत्तर साल के हैं।"}]}',
'{"title":"X साल के/की हूँ/है/हैं — X years old (age construction)","pattern":"X साल का/की हूँ/है = I am/he/she is X years old. X साल के/की हैं = they/you (formal) are X years old. साल = year. का/की/के agrees with the person''s gender and number. Age question: आप कितने साल के/की हैं? = How old are you?","explanation":"Age in Hindi: X + साल + का/की/के + हूँ/है/हैं. साल (saal) = year. Agreement: masculine singular: X साल का हूँ (I am X years old — male). Feminine singular: X साल की हूँ (female). Formal/plural: X साल के हैं (they are X years old). Age question: कितने साल के/की हैं? (kitne saal ke/ki hain = how many years old are they/you?). Example: मैं बीस साल का हूँ = I am twenty years old (male). मैं बीस साल की हूँ = I am twenty years old (female).","examples":[{"sentence":"वह पंद्रह साल की है।","transliteration":"Vah pandrah saal ki hai.","translation":"She is fifteen years old."},{"sentence":"आप कितने साल के हैं?","transliteration":"Aap kitne saal ke hain?","translation":"How old are you?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"पचास means?","options":["fifty","forty","sixty","fifteen"],"correctAnswer":"fifty"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My grandfather is seventy-five years old.","options":["मेरे दादाजी पचहत्तर साल के हैं।","मेरे नानाजी पचहत्तर साल के हैं।","मेरे दादाजी पचास साल के हैं।","मेरे दादाजी पचहत्तर साल की हैं।"],"correctAnswer":"मेरे दादाजी पचहत्तर साल के हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"वह पंद्रह साल ___ है।","options":["की","का","के","को"],"correctAnswer":"की"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: How old are you?","wordBankItems":["आप","कितने","साल","के","हैं","?"],"correctAnswer":"आप कितने साल के हैं ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"सौ means?","options":["one hundred","fifty","thousand","ten"],"correctAnswer":"one hundred"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000014',1,'APPROVED','PUBLISHED',
'{"objectives":["Express likes and dislikes in Hindi at A1","Use मुझे पसंद है/नहीं है","Talk about hobbies and preferences"],"explanation":{"intro":"Likes and dislikes vocabulary covers preferences, hobbies, and how to agree or disagree about them in Hindi at A1.","culturalNote":"पसंद और नापसंद — Likes and Dislikes: पसंद (pasand) = liking, preference (from Persian — same root as English ''pleasant'' via Latin placere). नापसंद (naapasand) = dislike (na = negative prefix + pasand). मुझे X पसंद है = I like X. मुझे X पसंद नहीं है = I don''t like X. Hobby vocabulary: किताबें पढ़ना (kitaben padhna = reading books), संगीत सुनना (sangeet sunna = listening to music), क्रिकेट खेलना (cricket khelna = playing cricket), खाना बनाना (khaana banaana = cooking). Cultural: Cricket (क्रिकेट) is a national passion — ''religion of India'' — IPL (Indian Premier League). Bollywood (बॉलीवुड) — Hindi film industry — world''s most prolific. Classical Indian music: Hindustani (North) and Carnatic (South). Street food: most Indians would say they love street food. Chai: universal preference. अच्छा/बुरा (acha/bura = good/bad) also used to express general evaluations."},"examples":[{"hindi":"मुझे क्रिकेट खेलना बहुत पसंद है।","transliteration":"Mujhe cricket khelna bahut pasand hai.","english":"I like playing cricket very much."},{"hindi":"मुझे गर्मी पसंद नहीं है।","transliteration":"Mujhe garmi pasand nahi hai.","english":"I don''t like the heat."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express likes and dislikes in Hindi and talk about hobbies."}}',
'{"items":[{"word":"पसंद","translation":"liking/preference","transliteration":"pasand","pronunciation":"pa-SAND","example":"मुझे पसंद है।"},{"word":"नापसंद","translation":"dislike","transliteration":"naapasand","pronunciation":"naa-pa-SAND","example":"मुझे नापसंद है।"},{"word":"खेलना","translation":"to play","transliteration":"khelna","pronunciation":"KHEL-na","example":"खेलना पसंद है।"},{"word":"संगीत","translation":"music","transliteration":"sangeet","pronunciation":"san-GEET","example":"संगीत सुनना।"},{"word":"बहुत","translation":"very/a lot","transliteration":"bahut","pronunciation":"ba-HUT","example":"बहुत पसंद है।"},{"word":"नहीं","translation":"no/not","transliteration":"nahi","pronunciation":"na-HEE","example":"पसंद नहीं है।"}]}',
'{"title":"मुझे X पसंद नहीं है — I don''t like X (negation with नहीं)","pattern":"Negation: नहीं (nahi) placed before the verb. मुझे X पसंद नहीं है = I don''t like X (nahi before hai). General negation: S + V + नहीं + auxiliary. Example: मैं जाता नहीं हूँ / मैं नहीं जाता हूँ = I don''t go (both positions possible — नहीं before the main verb is most common).","explanation":"Negation in Hindi: नहीं (nahi) = no/not — placed before the verb or auxiliary. Position options: (1) before the main verb: मैं नहीं जाता (main nahi jaata = I don''t go); (2) before the auxiliary: मैं जाता नहीं हूँ (less common). For मुझे X पसंद है: negation → मुझे X पसंद नहीं है (nahi before hai). मत (mat) = don''t (imperative prohibition — मत जाओ = don''t go). ना (na) = softer negation/request. Key: नहीं for statements; मत for commands.","examples":[{"sentence":"मुझे सब्ज़ी पसंद नहीं है।","transliteration":"Mujhe sabzi pasand nahi hai.","translation":"I don''t like vegetables."},{"sentence":"वह स्कूल नहीं जाता।","transliteration":"Vah school nahi jaata.","translation":"He doesn''t go to school."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"पसंद means?","options":["liking/preference","dislike","joy","sadness"],"correctAnswer":"liking/preference"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I like playing cricket very much.","options":["मुझे क्रिकेट खेलना बहुत पसंद है।","मुझे क्रिकेट देखना बहुत पसंद है।","मुझे फुटबॉल खेलना बहुत पसंद है।","मुझे क्रिकेट खेलना पसंद नहीं है।"],"correctAnswer":"मुझे क्रिकेट खेलना बहुत पसंद है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मुझे सब्ज़ी पसंद ___ है।","options":["नहीं","बहुत","भी","और"],"correctAnswer":"नहीं"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He doesn''t go to school.","wordBankItems":["वह","स्कूल","नहीं","जाता","।"],"correctAnswer":"वह स्कूल नहीं जाता ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"नहीं means?","options":["no/not","never","nothing","nobody"],"correctAnswer":"no/not"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

